        # Inter-Consumer Barriers (Seesaw Sync)
        bar_stats_0_ready = T.alloc_barrier(arrive_count=128)  # Cons 0 arrives
        bar_stats_1_ready = T.alloc_barrier(arrive_count=128)  # Cons 1 arrives

